begin;

do $$
begin
  if (
    select count(*)
    from public.trolley_types
    where trolley_type_code in ('SMALL', 'MEDIUM', 'LARGE')
      and active = true
      and deleted_at is null
  ) <> 3 then
    raise exception 'SMALL, MEDIUM and LARGE trolley types must exist before registry import.';
  end if;
end;
$$;

