),
normalized as (
  select
    source_row,
    trim(trolley_code) as trolley_code,
    upper(trim(trolley_type_code)) as trolley_type_code,
    source_status,
    source_metadata,
    case
      when upper(trim(source_status)) = 'OUT OF SERVICE' then 'OUT_OF_SERVICE'
      else 'LOCATION_UNCONFIRMED'
    end as initial_status
  from source_rows
),
inserted as (
  insert into public.trolleys (
    trolley_code,
    trolley_type_id,
    status,
    status_before_service_hold,
    active,
    registered_on,
    notes,
    metadata
  )
  select
    n.trolley_code,
    tt.trolley_type_id,
    n.initial_status,
    case when n.initial_status = 'OUT_OF_SERVICE' then 'LOCATION_UNCONFIRMED' else null end,
    true,
    date '2026-08-04',
    case
      when n.source_metadata ? 'data_quality_flag'
        then 'Imported from the physical trolley registry. Code retained exactly as supplied and flagged for review.'
      else 'Imported from the physical trolley registry. Initial physical location was not supplied.'
    end,
    n.source_metadata
  from normalized n
  join public.trolley_types tt
    on tt.trolley_type_code = n.trolley_type_code
   and tt.active = true
   and tt.deleted_at is null
  on conflict (trolley_code) do nothing
  returning trolley_id
)
select count(*) as inserted_trolley_count
from inserted;

commit;

select jsonb_build_object(
  'status', 'IMPORT_COMPLETE',
  'batch', 'CENTRALDB_TROLLEY_2026_08_04',
  'registry_count', count(*),
  'small', count(*) filter (where tt.trolley_type_code = 'SMALL'),
  'medium', count(*) filter (where tt.trolley_type_code = 'MEDIUM'),
  'large', count(*) filter (where tt.trolley_type_code = 'LARGE'),
  'location_unconfirmed', count(*) filter (where t.status = 'LOCATION_UNCONFIRMED'),
  'out_of_service', count(*) filter (where t.status = 'OUT_OF_SERVICE'),
  'data_quality_flags', count(*) filter (where t.metadata ? 'data_quality_flag')
)
from public.trolleys t
join public.trolley_types tt
  on tt.trolley_type_id = t.trolley_type_id
where t.metadata ->> 'registry_import_batch' = 'CENTRALDB_TROLLEY_2026_08_04';
